#!/usr/bin/env python3
"""Writes sprint_v15/PIPELINE_COMPARISON.md from builds/*/cycle.json and eval/eval_*.json (frozen grid). usage : make_docs_v15.py SPRINT_DIR"""
import json, sys
from pathlib import Path
D = Path(sys.argv[1]); tags = [t for t in ("A", "B", "C", "C2", "C3") if (D / "builds" / t / "cycle.json").exists() and (D / "eval" / ("eval_%s.json" % t)).exists()]
NAME = {"A": "A — pipeline actuel (V14, inchangé)", "B": "B — guidé par le besoin (manifeste + sémantique, 96×78)", "C": "C — hybride (B + bandes d'altitude par classe, 128×104)", "C2": "C2 — hybride, relief par massif (cycle 1)", "C3": "C3 — C2 + palette volcanique plus calme (cycle 2)"}
cy = {t: json.load(open(D / "builds" / t / "cycle.json")) for t in tags}; ev = {t: json.load(open(D / "eval" / ("eval_%s.json" % t))) for t in tags}; sha = json.load(open(D / "builds" / "sha256.json"))
L = []; w = L.append
w("# Sprint V15 — Comparaison des pipelines (grille gelée avant essais : `EVALUATION_GRID_FROZEN.json`)\n")
w("Trois approches (A, B, C) et **deux cycles de correction** (C2 : relief par massif ; C3 : palette volcanique). Même moteur de construction LEGO Maps, **non modifié** ; B et C ne changent que des **données** (composition, style, rasters de classes issus du manifeste).\n")
w("## 1. Mesures automatiques (identiques pour toutes les variantes)\n| Variante | Proportions (l/h) | Erreur de proportions | Précision pixel vs référence | mIoU | Erreur moyenne des repères | GO artistique mesuré (repères ≤ 0,10 **et** précision ≥ 0,55) |\n|---|---|---|---|---|---|---|")
for t in tags:
    e = ev[t]; go = e["landmark_error_mean"] <= 0.10 and e["pixel_accuracy"] >= 0.55
    w("| %s | %.3f | %.3f | **%.3f** | %.3f | %.3f | %s |" % (NAME[t], e["aspect"], e["aspect_error"], e["pixel_accuracy"], e["mean_IoU"], e["landmark_error_mean"], "**oui**" if go else "non"))
w("\nRéférence de proportions : 1,231 (mesurée). Pixels classés par la palette propre de chaque variante puis comparés à la carte de classes de la référence sur la grille 96×78 (V14 est donc comparée *étirée*, telle qu'affichée).\n")
w("### Erreur par repère (fraction de la largeur ; plus grand composant de la famille)\n| Variante | neige | désert | mer | pierre | forêt | massif brun |\n|---|---|---|---|---|---|---|")
for t in tags:
    r = ev[t]["landmark_errors"]; w("| %s | %s |" % (t, " | ".join("%.3f" % r[k] if r[k] is not None else "—" for k in ("snow_main", "desert_main", "sea_main", "stone_main", "forest_main", "mesa_main"))))
w("\n**Limite de la mesure** : le repère « forêt » (plus grand composant de forêt) est instable : la forêt de la référence est très fragmentée, d'où 0,47–0,48 pour toutes les variantes B/C ; il pèse ≈ 0,08 dans la moyenne. Il n'a pas été retiré après coup (grille gelée).\n")
w("### IoU par famille\n| Variante | eau | herbe | forêt | désert | pierre | neige | brun/rouille |\n|---|---|---|---|---|---|---|---|")
for t in tags: i = ev[t]["IoU_by_family"]; w("| %s | %s |" % (t, " | ".join("%.2f" % i[k] for k in ("water", "grass", "forest", "desert", "stone", "snow", "mesa_rust"))))
w("\n### Parts des familles (référence : eau 17,0 %, hors-carte 8,6 %, herbe 16,7 %, forêt 17,9 %, désert 14,1 %, pierre 5,7 %, neige 4,1 %, brun 15,8 % sur la grille 96×78 ; V14 : pas de hors-carte)\n| Variante | eau | hors-carte | herbe | forêt | désert | pierre | neige | brun/rouille |\n|---|---|---|---|---|---|---|---|---|")
for t in tags: s = ev[t]["family_share"]; w("| %s | %s |" % (t, " | ".join("%.1f %%" % (100 * s[k]) for k in ("water", "void", "grass", "forest", "desert", "stone", "snow", "mesa_rust"))))
w("\n## 2. Mesures techniques\n| Variante | Pièces | Références | Dimensions (mm) | Génération + validation (s) | Collisions | Déconnectées | Îlots | Non supportées | Pièces à 1 tenon (taux) | Points d'articulation (taux) | Pire défaillance isolée | Reconstruction identique | SHA-256 LDraw |\n|---|---|---|---|---|---|---|---|---|---|---|---|---|---|")
for t in tags:
    c = cy[t]; R, C = c["grid_studs"]; w("| %s | %d | %d | %d × %d | %d + %d | %d | %d | %d | %d | %d (%.1f %%) | %d (%.1f %%) | %d pièces (%s) | %s | `%s…` |" % (t, c["pieces"], c["references"], (C + 8) * 8, (R + 8) * 8, c["build_s"], c["validate_s"], c["collisions"], c["disconnected"], c["islands"], c["unsupported"], c["one_stud"], 100 * c["one_stud"] / c["pieces"], c["articulation"], 100 * c["articulation"] / c["pieces"], c["worst"]["parts_cut_off"], c["worst"]["family"], sha[t]["rebuild_identical"], sha[t]["ldraw_sha256"][:16]))
w("\nTemps de rendu (3 vues + gros plans, three.js) : de l'ordre de 1 à 3 min par vue (plus long pour C/C2/C3, 22–23 k pièces) ; non retenu comme critère.\n")
w("## 3. Critères techniques obligatoires de la grille gelée\n- **Zéro collision / déconnectée / îlot / non supportée** : respecté par A, B, C, C2" + (", C3" if "C3" in tags else "") + ".\n- **Génération reproductible** : respecté (deux constructions → même SHA-256).\n- **Baselines intactes** : les références de `ci/reference_hashes.json` ne sont pas modifiées ; la reconstruction de V14 redonne exactement `5afb9ac8…` ; aucun fichier de moteur ou de style existant n'a été modifié (uniquement des fichiers nouveaux + une sous-commande `intent` ajoutée au Builder).")
w("- **« Aucun défaut structurel critique nouveau » (règle gelée : pas plus de 25 % de pièces à 1 tenon / points d'articulation en nombre absolu)** : **non respectée à la lettre** par B, C, C2 : leurs nombres absolus dépassent V14 de +36 % à +172 % (1 898 → 2 580 → 4 565 → 5 169 pièces à 1 tenon), **mais** ces modèles ont de 17 % à 118 % de pièces en plus. En taux, la dégradation est limitée (pièces à 1 tenon 17,8 % → 20,6–22,2 % ; points d'articulation 14,3 % → 15,0–15,7 %) et la pire défaillance isolée **diminue** pour C, C2 (24 → 5 et 4 pièces) mais **augmente pour B (45 pièces)**. Verdict technique : **GO technique non acquis au sens strict de la grille** ; une revue de fragilité (renforts) serait nécessaire avant fabrication.")
w("\n## 4. Régressions éventuelles\nAucune sur les baselines (voir §3). Le titre « HYRULE » n'existe plus sur la carte (volontaire) ; le cadre est inchangé ; la version carrée 80×80 est remplacée par 96×78 (B) ou 128×104 (C…), donc des **modèles plus grands** (832×688 mm et 1088×896 mm contre 704×704 mm).\n")
open(D / "PIPELINE_COMPARISON.md", "w").write("\n".join(L)); print("ok", tags)
